/* Relay layout coherence v20 */
/* One vertical scroll surface, tighter desktop balance, daylight-readable handoff graph. */
html,body,.shell{
  height:100%;
  min-height:0;
}
body{
  overflow:hidden!important;
}
.shell{
  height:100dvh;
  min-height:100dvh;
  overflow:hidden;
}
header{
  flex:0 0 68px;
}
#workspace,
#workspace.open,
#workspace.working{
  height:calc(100dvh - 68px)!important;
  min-height:0!important;
  overflow:hidden!important;
}

/* The conversation owns vertical scrolling. Individual messages do not. */
.thread{
  min-height:0!important;
  overflow-y:auto!important;
  overflow-x:hidden!important;
  overscroll-behavior:contain;
  scrollbar-gutter:stable;
}
.presentationBody{
  max-height:none!important;
  overflow-y:visible!important;
  overflow-x:visible!important;
}
.presentationExpanded .presentationBody{
  max-height:none!important;
  overflow:visible!important;
}
.handwrittenIntro{
  max-height:none!important;
  overflow:visible!important;
}
.artifactTableWrap{
  overflow-x:auto!important;
  overflow-y:visible!important;
}
.presentationResult .messageBubble{
  width:100%!important;
  max-width:100%!important;
}

/* Keep conversation, tool rail and composer on one visual axis. */
#workspace.open .thread,
#workspace.open .toolDock,
#workspace.open .followup,
#workspace.working .thread,
#workspace.working .toolDock,
#workspace.working .followup{
  width:min(1040px,calc(100% - 40px))!important;
}
#workspace.open .messageRow.assistant .messageBubble,
#workspace.working .messageRow.assistant .messageBubble{
  max-width:94%!important;
}
#workspace.open .messageRow.user .messageBubble,
#workspace.working .messageRow.user .messageBubble{
