  box-shadow:0 0 9px rgba(113,239,255,.66),0 0 20px rgba(113,239,255,.25);
  transition:width .38s cubic-bezier(.2,.85,.2,1);
}
.activityCourier{
  position:absolute;
  left:calc(6% + (88% * var(--lane-progress)) / 100);
  top:17px;
  width:10px;height:10px;
  margin-left:-5px;
  border-radius:50%;
  background:#eaffff;
  box-shadow:0 0 7px #fff,0 0 16px var(--cyan),0 0 34px rgba(113,239,255,.62);
  transition:left .38s cubic-bezier(.2,.85,.2,1);
  z-index:4;
}
.activityLane[data-mode="busy"] .activityCourier,
.activityLane[data-mode="listening"] .activityCourier{
  animation:laneCourier .62s ease-in-out infinite alternate;
}
.activityNode{
  justify-self:center;
  width:86px;
  text-align:center;
  position:relative;
  z-index:5;
  color:#607286;
  transition:transform .26s cubic-bezier(.2,.85,.2,1),color .24s,filter .24s;
}
.activityNode b{
  width:28px;height:28px;
  margin:0 auto 5px;
  display:grid;
  place-items:center;
  border-radius:50%;
  border:1px solid rgba(139,167,193,.16);
  background:rgba(10,18,28,.94);
  color:#6f8194;
