  color:#8bf0c3;
  border-color:rgba(82,242,178,.26);
  box-shadow:0 0 12px rgba(82,242,178,.10),inset 0 0 12px rgba(82,242,178,.05);
}
.activityNode.active{
  color:#c9fbff;
  transform:translateY(-3px) scale(1.08);
  filter:brightness(1.16);
}
.activityNode.active b{
  color:#fff;
  border-color:rgba(181,250,255,.88);
  background:radial-gradient(circle,rgba(113,239,255,.18),rgba(8,16,25,.96) 62%);
  box-shadow:0 0 8px rgba(255,255,255,.42),0 0 22px rgba(113,239,255,.48),0 0 48px rgba(113,239,255,.18);
  animation:laneNodePulse .52s ease-in-out infinite alternate;
}
.activityNode.arrival b{animation:laneArrival .78s cubic-bezier(.2,.9,.25,1)}
.activityStars{position:absolute;inset:0;pointer-events:none;overflow:hidden;opacity:0}
.activityLane[data-mode="busy"] .activityStars,
.activityLane[data-mode="listening"] .activityStars{opacity:1}
.activityStars i{
  position:absolute;
  left:-70px;
  width:44px;height:1px;
  border-radius:999px;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.18),rgba(113,239,255,.92));
  box-shadow:0 0 8px rgba(113,239,255,.62);
  animation:laneStar 1.8s linear infinite;
}
.activityStars i:nth-child(1){top:12px;animation-duration:1.45s}
.activityStars i:nth-child(2){top:27px;animation-delay:.38s;animation-duration:1.9s}
.activityStars i:nth-child(3){top:43px;animation-delay:.82s;animation-duration:1.58s}
.activityStars i:nth-child(4){top:54px;animation-delay:1.15s;animation-duration:2.15s}
.activityLane[data-mode="done"]{
  border-color:rgba(82,242,178,.14);
  box-shadow:inset 0 0 22px rgba(82,242,178,.02);
}
.activityLane[data-mode="done"] .activityCourier{
  background:#dffff0;
  box-shadow:0 0 8px #fff,0 0 18px rgba(82,242,178,.82),0 0 36px rgba(82,242,178,.42);
}
@keyframes laneCourier{
  from{transform:scale(.78);filter:brightness(.9)}
  to{transform:scale(1.32);filter:brightness(1.35)}
}
@keyframes laneNodePulse{
  from{transform:scale(.96) translateY(1px)}
  to{transform:scale(1.13) translateY(-1px)}
}
@keyframes laneArrival{
  0%{transform:scale(.7)}
  45%{transform:scale(1.55);box-shadow:0 0 14px #fff,0 0 36px rgba(82,242,178,.8)}
  100%{transform:scale(1)}
}
@keyframes laneStar{
  0%{left:-70px;opacity:0;transform:translateX(0) skewX(-18deg)}
  10%{opacity:.9}
  84%{opacity:.75}
  100%{left:calc(100% + 20px);opacity:0;transform:translateX(30px) skewX(-18deg)}
}
